const vertexSource = `
precision highp float;
attribute vec3 aPosition;
varying vec2 uv;
void main() {
  uv = (aPosition.xy + 1.0) * 0.5;
  gl_Position = vec4(aPosition, 1.0);
}`;
const fragment = `
precision highp float;
varying vec2 uv;
void main() {
  gl_FragColor = vec4(uv.x, 0.3, uv.y, 1.0);
}`;
let gradient;
function setup() {
  createCanvas(400, 280, WEBGL);
  gradient = createShader(vertexSource, fragment);
  noStroke();
}
function draw() {
  shader(gradient);
  beginShape(TRIANGLE_STRIP);
  vertex(-1, -1, 0); vertex(1, -1, 0);
  vertex(-1, 1, 0); vertex(1, 1, 0);
  endShape();
}

let engine, ball;
function setup() {
  createCanvas(400, 280);
  engine = Matter.Engine.create();
  ball = Matter.Bodies.circle(200, 40, 24, { restitution: 0.75 });
  const floor = Matter.Bodies.rectangle(200, 270, 400, 20, { isStatic: true });
  Matter.Composite.add(engine.world, [ball, floor]);
}
function draw() {
  Matter.Engine.update(engine, 1000 / 60);
  background('#F1F1EA');
  noStroke();
  fill('#426B5D'); rect(0, 260, 400, 20);
  fill('#B85338'); circle(ball.position.x, ball.position.y, 48);
}

